fn clip(arr: &Vec<i8>, min_val: i8, max_val: i8) -> Vec<i8> {
    if min_val > max_val {
        // When min_val > max_val, return vector filled with max_val
        vec![max_val; arr.len()]
    } else {
        // When min_val ≤ max_val, clip each value to the range
        arr.iter()
            .map(|&x| {
                if x < min_val {
                    min_val
                } else if x > max_val {
                    max_val
                } else {
                    x
                }
            })
            .collect()
    }
}